ition: fixed;\n      inset: 0;\n      z-index: 0;\n      pointer-events: none;\n      opacity: 0.6;\n      background-image:\n        radial-gradient(closest-side at 42% 44%, transparent 0 30%, rgba(90, 120, 160, 0.05) 31% 32%, transparent 33%),\n        radial-gradient(closest-side at 42% 44%, transparent 0 45%, rgba(90, 120, 160, 0.04) 46% 47%, transparent 48%),\n        radial-gradient(closest-side at 74% 46%, transparent 0 30%, rgba(90, 120, 160, 0.045) 31% 32%, transparent 33%),\n        linear-gradient(rgba(90, 115, 150, 0.05) 1px, transparent 1px),\n        linear-gradient(90deg, rgba(90, 115, 150, 0.05) 1px, transparent 1px),\n        linear-gradient(rgba(80, 105, 145, 0.09) 1px, transparent 1px),\n        linear-gradient(90deg, rgba(80, 105, 145, 0.09) 1px, transparent 1px);\n      background-size:\n        auto, auto, auto,\n        34px 34px, 34px 34px,\n        170px 170px, 170px 170px;\n    }\n\n    /* Soft inner-shadow frame */\n    body::after {\n      content: '';\n      position: fixed;\n      inset: 0;\n      z-index: 1;\n      pointer-events: none;\n      background: rgba(45, 65, 95, 0.025);\n      box-shadow: inset 0 0 160px rgba(70, 95, 135, 0.2);\n    }\n\n    /* Slightly deepen only the map backdrop in compact embedded viewports. */\n    @media (max-width: 720px), (max-height: 520px) {\n      body::after {\n        background: rgba(45, 65, 95, 0.05);\n        box-shadow: inset 0 0 110px rgba(55, 78, 112, 0.24);\n      }\n    }\n\n    #map-container {\n      position: relative;\n      width: 100%;\n      height: 100%;\n      z-index: 2;\n      overflow: hidden;\n      cursor: grab;\n    }\n\n    #map-container.grabbing {\n      cursor: grabbing;\n    }\n\n    #edge-canvas {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n    }\n\n    #node-layer {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      pointer-events: none;\n    }\n\n    .node-wrapper {\n      position: absolute;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      pointer-events: auto;\n      cursor: pointer;\n      transform: translate(-50%, -50%);\n      transition: filter 0.2s;\n    }\n\n    .node-wrapper:hover {\n      filter: brightness(1.05) drop-shadow(0 4px 10px rgba(40, 70, 110, 0.28));\n    }\n\n    .node-icon svg {\n      display: block;\n      filter: drop-shadow(0 2px 4px rgba(40, 65, 100, 0.28));\n    }\n\n    /* ============ FLAT ICON DISCS (light-modern) ============ */\n    .node-icon {\n      position: relative;\n      z-index: 2;\n      display: grid;\n      place-items: center;\n      border-radius: 50%;\n      color: var(--nc, #6b7d94);\n      background: #fff;\n      border: 2px solid var(--nc, #6b7d94);\n      box-shadow: 0 3px 9px -2px rgba(40, 65, 100, 0.28), inset 0 0 0 3px rgba(255, 255, 255, 0.9);\n    }\n\n    /* major (city/campus/stronghold): solid colored disc, white glyph */\n    .node-wrapper[data-tier=\"major\"] .node-icon {\n      color: #fff;\n      background: var(--nc, #2f7fd6);\n      border-color: #fff;\n      box-shadow: 0 5px 14px -3px var(--nc, #2f7fd6), 0 0 0 1px rgba(255, 255, 255, 0.6);\n    }\n\n    .node-wrapper[data-tier=\"major\"] .node-icon::after {\n      content: '';\n      position: absolute;\n      inset: -5px;\n      border-radius: 50%;\n      border: 1.5px solid var(--nc, #2f7fd6);\n      opacity: 0.32;\n    }\n\n    /* scene: tiny colored dot (icon glyph hidden) */\n    .node-wrapper[data-type=\"scene\"] .node-icon {\n      border: 2px solid #fff;\n      background: var(--nc, #6b7d94);\n      box-shadow: 0 1px 4px -1px rgba(40, 65, 100, 0.5);\n    }\n\n    .node-wrapper[data-type=\"scene\"] .node-icon svg {\n      display: none;\n    }\n\n    /* otherspace: keep the original ornate colored icon, no white disc */\n    .node-wrapper[data-type=\"otherspace\"] .node-icon {\n      background: transparent;\n      border: none;\n      box-shadow: none;\n    }\n\n    .node-wrapper[data-type=\"otherspace\"] .node-icon svg {\n      filter: drop-shadow(0 2px 5px rgba(80, 30, 110, 0.4));\n    }\n\n    .node-label {\n      position: relative;\n      z-index: 3;\n      margin-top: 6px;\n      white-space: nowrap;\n      text-align: center;\n      color: #1e2a3c;\n      font-weight: 600;\n      font-family: 'Inter', 'Noto Sans SC', sans-serif;\n      line-height: 1.3;\n      background: rgba(255, 255, 255, 0.92);\n      border: 1px solid rgba(110, 132, 165, 0.28);\n      padding: 2px 9px;\n      border-radius: 7px;\n      box-shadow: 0 2px 6px -2px rgba(40, 65, 100, 0.22);\n      backdrop-filter: blur(3px);\n    }\n\n    /* City/Campus/Stronghold emphasis */\n    .node-wrapper[data-tier=\"major\"] .node-icon svg {\n      filter: drop-shadow(0 3px 6px rgba(40, 65, 100, 0.32));\n    }\n\n    .node-wrapper[data-tier=\"major\"] .node-label {\n      color: #14203a;\n      font-weight: 700;\n    }\n\n    /* ============ DETAIL MODAL STYLES ============ */\n    .detail-overlay {\n      display: none;\n      position: fixed;\n      inset: 0;\n      z-index: 200;\n      background: rgba(60, 85, 120, 0.28);\n      backdrop-filter: blur(5px);\n      justify-content: center;\n      align-items: center;\n    }\n\n    .detail-overlay.active {\n      display: flex;\n    }\n\n    .detail-panel {\n      position: relative;\n      width: 90%;\n      max-width: 680px;\n      max-height: 85vh;\n      background: linear-gradient(165deg, #ffffff 0%, #f5f8fb 100%);\n      border: 1px solid rgba(120, 145, 180, 0.3);\n      border-radius: 16px;\n      overflow-y: auto;\n      padding: 0;\n      box-shadow: 0 24px 60px -12px rgba(30, 55, 90, 0.4);\n    }\n\n    .detail-panel::-webkit-scrollbar {\n      width: 7px;\n    }\n\n    .detail-panel::-webkit-scrollbar-track {\n      background: transparent;\n    }\n\n    .detail-panel::-webkit-scrollbar-thumb {\n      background: rgba(120, 145, 180, 0.4);\n      border-radius: 4px;\n    }\n\n    .detail-